<?php
namespace App\Http\Controllers;
use App\Models\{TaxCode,Account};use Illuminate\Http\Request;
class TaxCodeController {public function index(){return view('taxes.index',['taxes'=>TaxCode::forCompany(auth()->user()->company_id)->orderBy('code')->get(),'accounts'=>Account::forCompany(auth()->user()->company_id)->where('is_postable',1)->orderBy('code')->get()]);}public function store(Request $r){$d=$r->validate(['code'=>'required|string|max:50','name'=>'required|string|max:255','rate'=>'required|decimal:0,5|min:0','type'=>'required|in:sales,purchase,both','sales_account_id'=>'nullable|integer','purchase_account_id'=>'nullable|integer']);$d['company_id']=$r->user()->company_id;TaxCode::create($d);return back()->with('ok','Tax code created.');}public function update(Request $r,TaxCode $taxCode){$d=$r->validate(['name'=>'required|string|max:255','rate'=>'required|decimal:0,5|min:0','active'=>'nullable|boolean']);$d['active']=$r->boolean('active');$taxCode->update($d);return back()->with('ok','Tax code updated.');}}
